"""Core word-level LCS diff implementation.

No difflib is used here: the longest-common-subsequence alignment between
the two token streams is computed from scratch with dynamic programming.
"""

from __future__ import annotations

import re

EQUAL = "equal"
DELETE = "delete"
INSERT = "insert"

_TOKEN_RE = re.compile(r"\S+")


def tokenize(text: str) -> list[str]:
    """Split text into word tokens (any run of non-whitespace)."""
    return _TOKEN_RE.findall(text)


def diff_ops(old: list[str], new: list[str]) -> list[tuple[str, str]]:
    """Return an ordered list of (op, token) pairs.

    op is one of EQUAL, DELETE, INSERT. At each mismatch gap, deletions
    are emitted before insertions (diff(1)-style grouping).
    """
    n, m = len(old), len(new)
    # lcs[i][j] = length of the LCS of old[i:] and new[j:]
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row_old = old[i]
        for j in range(m - 1, -1, -1):
            if row_old == new[j]:
                lcs[i][j] = lcs[i + 1][j + 1] + 1
            else:
                lcs[i][j] = max(lcs[i + 1][j], lcs[i][j + 1])

    ops: list[tuple[str, str]] = []
    i = j = 0
    while i < n and j < m:
        if old[i] == new[j]:
            ops.append((EQUAL, old[i]))
            i += 1
            j += 1
        elif lcs[i + 1][j] >= lcs[i][j + 1]:
            ops.append((DELETE, old[i]))
            i += 1
        else:
            ops.append((INSERT, new[j]))
            j += 1
    while i < n:
        ops.append((DELETE, old[i]))
        i += 1
    while j < m:
        ops.append((INSERT, new[j]))
        j += 1
    return ops


def format_diff(ops: list[tuple[str, str]]) -> str:
    """Render diff ops as a single line of text.

    Unchanged words appear plain, deletions as [-word-], insertions
    as {+word+}.
    """
    parts: list[str] = []
    for op, token in ops:
        if op == EQUAL:
            parts.append(token)
        elif op == DELETE:
            parts.append(f"[-{token}-]")
        else:
            parts.append(f"{{+{token}+}}")
    return " ".join(parts)


def diff_text(old_text: str, new_text: str) -> str:
    """Word-level diff of two texts, rendered as a string."""
    return format_diff(diff_ops(tokenize(old_text), tokenize(new_text)))

